// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount <= type(uint96).max);
        Rejecter rej = new Rejecter();
        address nonOwner = makeAddr("nonOwner");
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok = false;
        try c.Command{value: amount}(address(rej), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Non-owner Command to rejecter must revert");
    }
}

contract Rejecter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
